import { useState, useEffect } from 'react';
import Card from './componentes/Card';
import './App.css';

const INITIAL_ICONS = ['✨', ' 🎀', ' 🦢', '🤍', ' 🧸 ', ' 💌', '🍓', '🌷͙֒'];

function shuffle(array) {
  return [...array].sort(() => Math.random() - 0.5);
}

export default function App() {
  const [cards, setCards] = useState([]);
  const [flippedCards, setFlippedCards] = useState([]);
  const [matchedCards, setMatchedCards] = useState([]);
  const [moves, setMoves] = useState(0);
  const [lockBoard, setLockBoard] = useState(true);
  const [previewActive, setPreviewActive] = useState(false);

  const [showStartModal, setShowStartModal] = useState(true);
  const [showVictoryModal, setShowVictoryModal] = useState(false);
  const [countdown, setCountdown] = useState(null);
  const [isCounting, setIsCounting] = useState(false);

  useEffect(() => {
    initGame();
  }, []);

  const initGame = () => {
    const paired = [...INITIAL_ICONS, ...INITIAL_ICONS];
    const shuffled = shuffle(paired).map((icon, index) => ({
      id: index,
      icon: icon
    }));

    setCards(shuffled);
    setFlippedCards([]);
    setMatchedCards([]);
    setMoves(0);
    setLockBoard(true);
    setPreviewActive(false);
    setShowVictoryModal(false);
  };

  const startPreview = () => {
    setPreviewActive(true);
    setLockBoard(true);

    setTimeout(() => {
      setPreviewActive(false);
      setLockBoard(false);
    }, 1000);
  };

  const handleStartGame = () => {
    setIsCounting(true);
    let count = 3;
    setCountdown(count);

    const timer = setInterval(() => {
      count--;
      if (count > 0) {
        setCountdown(count);
      } else if (count === 0) {
        setCountdown("¡Ya!");
      } else {
        clearInterval(timer);
        setShowStartModal(false);
        setIsCounting(false);
        setCountdown(null);
        startPreview();
      }
    }, 1000);
  };

  const handleCardClick = (index) => {
    if (lockBoard) return;
    if (flippedCards.includes(index)) return;
    if (matchedCards.includes(index)) return;

    const newFlipped = [...flippedCards, index];
    setFlippedCards(newFlipped);

    if (newFlipped.length === 2) {
      setMoves((prev) => prev + 1);
      setLockBoard(true);

      const [firstIdx, secondIdx] = newFlipped;
      
      if (cards[firstIdx].icon === cards[secondIdx].icon) {
        const newMatched = [...matchedCards, firstIdx, secondIdx];
        setMatchedCards(newMatched);
        setFlippedCards([]);
        setLockBoard(false);

        if (newMatched.length === cards.length) {
          setTimeout(() => {
            setShowVictoryModal(true);
          }, 500);
        }
      } else {
        setTimeout(() => {
          setFlippedCards([]);
          setLockBoard(false);
        }, 1000);
      }
    }
  };

  const handleRestart = () => {
    initGame();
    setShowStartModal(true);
  };

  return (
    <main className="game-container">
      <h1>Memotest</h1>

      <div className="stats-board">
        <div className="stat">Movimientos: <span>{moves}</span></div>
        <button id="restart-btn" onClick={handleRestart}>Reiniciar Juego</button>
      </div>

      <div className="grid-container" id="grid">
        {cards.map((card, index) => {
          const isFlipped = previewActive || flippedCards.includes(index) || matchedCards.includes(index);
          return (
            <Card
              key={card.id}
              icon={card.icon}
              isFlipped={isFlipped}
              onClick={() => handleCardClick(index)}
            />
          );
        })}
      </div>

      {showStartModal && (
        <div id="start-modal" className="modal">
          <div className="modal-content">
            <h2>✨ Memotest ✨</h2>
            {!isCounting && <p>Presiona el botón para comenzar</p>}
            {!isCounting && (
              <button id="start-btn" onClick={handleStartGame}>Comenzar Partida</button>
            )}
            {countdown !== null && (
              <div id="countdown" style={{ fontSize: '2.5rem', marginTop: '15px', fontWeight: 'bold' }}>
                {countdown}
              </div>
            )}
          </div>
        </div>
      )}

      {showVictoryModal && (
        <div id="victory-modal" className="modal">
          <div className="modal-content">
            <h2>🎉 ¡Felicidades! 🎉</h2>
            <p>Completaste el juego en <span>{moves}</span> movimientos.</p>
            <button id="modal-restart-btn" onClick={handleRestart}>Jugar de nuevo</button>
          </div>
        </div>
      )}
    </main>
  );
}